#!/bin/sh
# Genera index.html autónomo (para cualquier hosting estático) a partir de page.html
cd "$(dirname "$0")"
{ printf '<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="application-name" content="AsterOrbis"><meta name="apple-mobile-web-app-title" content="AsterOrbis"><link rel="icon" href="assets/logo.svg" type="image/svg+xml"><link rel="icon" href="assets/icon-32.png" sizes="32x32" type="image/png"><link rel="apple-touch-icon" href="assets/apple-touch-icon.png"><script>if(location.protocol==="http:"&&/(^|\.)asterorbis\.com$/.test(location.hostname))location.replace("https://"+location.host+location.pathname+location.search+location.hash)</script><style>:root{color-scheme:light;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}body{margin:0;font:14px system-ui,sans-serif}img{max-width:100%%}[hidden]{display:none!important}</style></head><body>\n'; cat page.html; printf '\n</body></html>\n'; } > index.html
